}.admin-shell{max-width:1100px;margin:36px auto;padding:24px}.admin-header,.admin-shell .card{margin-bottom:18px;padding:24px;border:1px solid var(--line);border-radius:15px;background:#fff;box-shadow:0 8px 28px #0b245007}.admin-header h1{margin:0;color:#0b2750}.admin-header p{margin:5px 0 0;color:var(--muted);font-size:13px}.admin-shell form{display:grid;gap:12px}.admin-shell input,.admin-shell select,.admin-shell button{font:inherit;padding:11px;border:1px solid #cedbea;border-radius:8px}.admin-shell button{background:#125cb2;color:#fff;cursor:pointer}.admin-shell .row{display:flex;gap:18px;align-items:center;border-top:1px solid #e1e9f2;padding:16px 0;flex-wrap:wrap}.admin-shell .row img,.admin-shell .row video{width:230px;max-height:110px;object-fit:contain}.admin-shell .row form{display:inline}.admin-shell .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.admin-brand{display:flex;align-items:center;gap:12px}.admin-brand strong{font-size:21px}.admin-brand svg{width:29px;height:29px;fill:none;stroke:#1768d2;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}@media(max-width:780px){.login-shell{grid-template-columns:1fr;min-height:0;margin:16px auto;width:calc(100% - 28px);border-radius:19px}.brand-panel{min-height:250px;padding:26px}.brand-copy{margin:30px 0 22px}.brand-copy h1{font-size:32px}.brand-points{display:none}.brand-footer{padding-top:13px}.auth-panel{padding:30px 25px 35px}.auth-panel h2{font-size:26px}.admin-shell{margin:12px auto;padding:10px}}
