><script>const form=document.querySelector('#editor'),type=form.querySelector('#media-type'),file=form.querySelector('#media-file');type.onchange=()=>file.accept=type.value==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp';function editSlide(s){form.elements['id'].value=s.id;type.value=s.media_type;type.onchange();form.sort_order.value=s.sort_order;form.alt_text.value=s.alt_text;form.is_published.checked=!!Number(s.is_published);form.scrollIntoView({behavior:'smooth'})}</script></main>
